function renderDashboard(all=wishesFor('all')){const total=all.length,records=dashRecords(all);dashIntervals=records;const five=records.length,known=records.filter(x=>x.p!==null&&x.p>0);const rates=dashRate(records);
const period=all.length?dashDate(all.at(-1).time)+' — '+dashDate(all[0].time):'Импортируй историю';write('#dashPeriod',period);write('#dashRarity',fmt(all.filter(w=>Number(w.rank)===4).length)+' выпадений 4★');write('#dashDonutTotal',fmt(total));const nickname=String(state.nickname||'').trim();write('#dashWelcome',nickname?'Путешественник '+nickname+' · твоя личная хроника Тейвата.':'Твоя личная хроника путешествий по Тейвату.');
const legend=$('#dashLegend');legend.replaceChildren();const banners=$('#dashBannerCards');banners.replaceChildren();let pos=0;const stops=[];
for(const d of DASH_TYPES){const rows=all.filter(w=>dashType(w.type).id===d.id),count=rows.length,stars=rows.filter(w=>Number(w.rank)===5),share=total?count/total*100:0;if(d.id==='other'&&!count)continue;if(share){stops.push(d.color+' '+pos+'% '+(pos+share)+'%');pos+=share;}const line=dashNode('button','dash-legend-row');line.type='button';const dot=dashNode('i','dash-dot');dot.style.background=d.color;line.append(dot,dashNode('span','',d.short),dashNode('strong','',fmt(count)),dashNode('small','',share.toLocaleString('ru-RU',{maximumFractionDigits:1})+'%'));line.onclick=()=>openHistory(d.id);legend.append(line);
if(!count&&['100','500','other'].includes(d.id))continue;const card=dashNode('article','dash-banner-card');card.style.setProperty('--banner-color',d.color);const head=dashNode('div','dash-banner-head');head.append(dashNode('span','dash-banner-symbol',d.symbol),dashNode('h3','',d.label));card.append(head);const numbers=dashNode('div','dash-banner-numbers');const big=dashNode('div');big.append(dashNode('strong','',fmt(count)),dashNode('small','','молитв'));const tiny=dashNode('div');tiny.append(dashNode('strong','',fmt(stars.length)),dashNode('small','','5★'));numbers.append(big,tiny);card.append(numbers);
if(d.cap){const p=rows.length?pity(d.id):null;const exact=stars.length>0;const meter=dashNode('div','dash-pity-label');meter.append(dashNode('span','','Счётчик 5★'),dashNode('b','',p===null?'— / '+d.cap:(exact?'':'≥ ')+p+' / '+d.cap));const bar=dashNode('div','dash-pity-track'),fill=dashNode('i');fill.style.width=Math.min(100,(p||0)/d.cap*100)+'%';bar.append(fill);card.append(meter,bar,dashNode('p','dash-pity-note',p===null?'Нет истории':!exact?'Нет предыдущего 5★ в импорте':p<d.cap?'До предельного pity: '+(d.cap-p):'Проверь полноту истории'));}
const last=stars[0],lastWrap=dashNode('div','dash-last');lastWrap.append(dashNode('small','','Последнее 5★'));if(last){const rec=records.find(x=>x.w===last);lastWrap.append(itemLabel(lookupWish(last),last.name,(rec?.p==null?'Pity неизвестен':rec.p+' молитв')+' · '+dashDate(last.time),5));}else lastWrap.append(dashNode('p','hint','Пока нет выпадений'));card.append(lastWrap);const more=dashNode('button','ghost dash-more','История баннера →');more.onclick=line.onclick;card.append(more);banners.append(card);}
$('#dashDonut').style.background=total?'conic-gradient('+stops.join(',')+')':'#362b47';$('#dashDonut').setAttribute('aria-label',total?'Распределение '+total+' молитв по баннерам':'Нет импортированных молитв');
const luck=$('#dashLuck');luck.replaceChildren();const avg=known.length?(known.reduce((n,r)=>n+r.p,0)/known.length).toLocaleString('ru-RU',{maximumFractionDigits:1}):'—';dashMetric(luck,'Средний pity',avg,known.length+' полных интервалов');dashMetric(luck,'Самое раннее',known.length?Math.min(...known.map(x=>x.p)):'—','молитв до 5★');dashMetric(luck,'Самое позднее',known.length?Math.max(...known.map(x=>x.p)):'—','молитв до 5★');dashMetric(luck,'Победы в 50/50 (оценка)',rates.n?Math.round(100*rates.win/rates.n)+'%':'—',rates.n?rates.win+' побед / '+rates.loss+' проигрышей':'Недостаточно данных');dashMetric(luck,'5★ персонажей',fmt(records.filter(x=>lookupWish(x.w)?.k==='characters').length),'распознано по базе');dashMetric(luck,'5★ оружия',fmt(records.filter(x=>lookupWish(x.w)?.k==='weapons').length),'распознано по базе');
write('#dashLuckNote','Pity: только интервалы между двумя 5★ одной категории. Оценка 50/50: только распознанные ивентовые выпадения после предыдущего ивентового 5★; гарантированные и неоднозначные случаи исключены. Сияние пленённого света отдельно не определяется.');
const recent=$('#recentFive');recent.replaceChildren();if(!records.length)recent.append(dashNode('p','hint','Импортируй историю, чтобы здесь появилась коллекция твоих 5★.'));for(const r of records.slice(0,8)){const v=lookupWish(r.w),card=dashNode('article','dash-five-card');card.dataset.rank='5';card.style.setProperty('--banner-color',rarityStyle(5));const head=dashNode('div','dash-five-art');head.append(iconFor(v,5),dashNode('span','dash-five-pill',r.p===null?'?':r.p+' крут.'));const info=dashNode('div','dash-five-info');info.append(dashNode('strong','',dashName(r.w)),dashNode('span','gold','★★★★★'),dashNode('small','',dashType(r.t).short+' · '+dashDate(r.w.time)));card.append(head,info);recent.append(card);}
renderDashChart();}

let chartLastFilter=null;
function renderDashChart(){const wrap=$('#dashChart'),filter=$('#dashHistoryType').value,scale=$('#dashChartScale').value||'detail';const values=dashIntervals.filter(x=>filter==='all'||x.t===filter).slice().reverse();const prev=wrap.scrollLeft||0,wasEnd=wrap.scrollWidth-wrap.clientWidth-prev<24,changed=chartLastFilter!==filter;chartLastFilter=filter;wrap.dataset.scale=scale;wrap.replaceChildren();write('#dashChartCount',fmt(values.length)+' выпадений 5★'+(values.length?' · '+dashDate(values[0].w.time)+' — '+dashDate(values.at(-1).w.time):''));$('#dashChartFirst').disabled=$('#dashChartLast').disabled=!values.length;if(!values.length){wrap.append(dashNode('p','hint dash-chart-empty','Нет пятизвёздочных выпадений для выбранной категории.'));return;}const max=values.reduce((m,r)=>Math.max(m,r.p||0),90),plot=dashNode('div','dash-chart-plot');for(const val of [max,Math.round(max/2),0]){const grid=dashNode('div','dash-chart-line');grid.style.bottom=(val/max*100)+'%';grid.append(dashNode('span','',val));plot.append(grid);}const cols=dashNode('div','dash-chart-cols');for(const r of values){const el=dashNode('div','dash-chart-col');el.style.setProperty('--banner-color',dashType(r.t).color);const track=dashNode('div','dash-chart-track'),bar=dashNode('div','dash-chart-bar'+(r.p===null?' unknown':''));bar.style.height=(r.p===null?8:Math.max(2,r.p/max*100))+'%';bar.append(dashNode('span','',r.p===null?'?':r.p));track.append(bar);const label=dashNode('div','dash-chart-label');if(scale!=='overview')label.append(iconFor(lookupWish(r.w),5));label.append(dashNode('small','',dashName(r.w)));el.title=dashName(r.w)+' · '+dashType(r.t).short+' · '+(r.p===null?'Pity неизвестен':r.p+' молитв')+' · '+dashDate(r.w.time);el.tabIndex=0;el.setAttribute('aria-label',el.title);el.append(track,label);cols.append(el);}plot.append(cols);wrap.append(plot);wrap.scrollLeft=changed||wasEnd?wrap.scrollWidth:prev;}

function dashServerDate(){const offsets={eu:1,usa:-5,os:8,cn:8};const offset=offsets[state.server]??1;return new Date(Date.now()+offset*3600000).toISOString().replace('T',' ').slice(0,19);}
function renderDashCurrent(){const box=$('#dashCurrent');box.replaceChildren();const now=dashServerDate(),day=now.slice(0,10);const active=dashSchedule.filter(b=>['301','302','500'].includes(b.type)&&b.start<=now&&b.end>=now);for(const b of active){const d=dashType(b.type),card=dashNode('article','dash-live-card');card.style.setProperty('--banner-color',d.color);card.append(dashNode('span','eyebrow',d.label),dashNode('h4','',b.type==='302'?'Воплощение божества':b.type==='500'?'Молитва хроник':b.featured.map(dashItemName).join(' / ')));const art=dashNode('div','dash-live-art');for(const id of b.featured){const v=lookupItem(id),cell=dashNode('div','dash-live-item');cell.append(iconFor(v,5),dashNode('small','',dashItemName(id)));art.append(cell);}card.append(art);const days=Math.max(0,Math.ceil((Date.parse(b.end.replace(' ','T')+'Z')-Date.parse(now.replace(' ','T')+'Z'))/86400000));card.append(dashNode('small','dash-live-date',dashDate(b.start)+' — '+dashDate(b.end)+' · ≈ '+days+' дн.'));box.append(card);}
const st=dashNode('article','dash-live-card standard');st.style.setProperty('--banner-color','#76bbeb');st.append(dashNode('span','eyebrow','ПОСТОЯННАЯ МОЛИТВА'),dashNode('h4','','Жажда странствий'));const art=dashNode('div','dash-live-art');for(const id of ['mona','diluc','jean','qiqi','keqing']){const v=lookupItem(id);if(v)art.append(iconFor(v,5));}st.append(art,dashNode('small','dash-live-date','Без ограничения по времени · иллюстрация пула'));box.append(st);
if(!active.length){const p=dashNode('p','hint','В доступном расписании нет подтверждённых активных ивентовых баннеров на '+dashDate(day)+'. Сверь календарь или игру.');box.prepend(p);}write('#dashScheduleNote','Источник расписания: Paimon.moe · '+(dashScheduleLive?'обновлено из открытой базы':'локальный снимок базы')+' · время сервера приблизительное; актуальность сверяй в игре.');}
function parseDashSchedule(source){const out=[];let type;for(const match of source.matchAll(/^  (beginners|standard|characters|weapons|chronicled): \[|^    \{([\s\S]*?)^    \},?/gm)){if(match[1]){type=({beginners:'100',standard:'200',characters:'301',weapons:'302',chronicled:'500'})[match[1]];continue;}const s=match[2];if(!type||!s)continue;const prop=k=>s.match(new RegExp("\\b"+k+"\\s*:\\s*(['\"])(.*?)\\1"))?.[2];const arr=s.match(/\bfeatured\s*:\s*\[([\s\S]*?)\]/)?.[1]||'';const featured=[...arr.matchAll(/['"]([^'"]+)['"]/g)].map(m=>m[1]);const start=prop('start'),end=prop('end');if(!start||!end)continue;out.push({type,name:prop('name'),start,end,featured,version:prop('version')||'',zone:/timezoneDependent:\s*true/.test(s)});}return out;}
async function refreshDashSchedule(){try{const r=await fetch('https://raw.githubusercontent.com/MadeBaruna/paimon-moe/main/src/data/banners.js',{cache:'no-cache',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)return;const src=await r.text();if(src.length>1000000)return;const data=parseDashSchedule(src);if(data.length<100||!data.some(x=>x.type==='302'))return;const latest=x=>x.filter(b=>['301','302','500'].includes(b.type)).map(b=>b.end).sort().at(-1)||'';if(latest(data)<latest(dashSchedule))return;dashSchedule=data;dashScheduleLive=true;renderDashCurrent();renderDashboard();}catch{}}
function renderDashGoal(now,total,worst,ww){const include=!!state.goalIncludeWeapon,need=worst+(include?ww:0),missing=Math.max(0,need-total);write('#dashGuarantee',state.guarantee?'Гарант персонажа: да (вручную)':'Гарант персонажа: не отмечен');write('#dashProjected','К сроку: '+fmt(total)+' молитв');const box=$('#dashGoalView');box.replaceChildren();const char=lookupItem(state.goalCharacter),weapon=lookupItem(state.weaponWishName);const metrics=dashNode('div','dash-goal-numbers');dashMetric(metrics,'Сейчас',fmt(now),'молитв');dashMetric(metrics,'К сроку',fmt(total),'молитв');dashMetric(metrics,'До полной гарантии',fmt(need),'максимум');dashMetric(metrics,'Не хватает',fmt(missing),'к сроку');box.append(metrics);$('#dashGoalBar').style.width=Math.min(100,total/Math.max(need,1)*100)+'%';write('#dashGoalText',Math.round(Math.min(100,total/Math.max(need,1)*100))+'% от консервативной цели · настройки pity, сроков и гаранта берутся из калькулятора.');}
function initDashboard(){$('#dashHistoryType').addEventListener('change',renderDashChart);$('#dashChartScale').addEventListener('change',()=>{chartLastFilter=null;renderDashChart();});$('#dashChartFirst').onclick=()=>{$('#dashChart').scrollLeft=0;};$('#dashChartLast').onclick=()=>{$('#dashChart').scrollLeft=$('#dashChart').scrollWidth;};renderDashCurrent();refreshDashSchedule();}



let historyRank='all',historyRevision=0,historyKey=null;
function cleanGameName(name){return String(name??'').replace(/^\s*#/,'').replace(/\{SPACE\}/gi,' ').replace(/\s+/g,' ').trim();}
const rarityStyle=r=>r===5?'#e8bd77':r===4?'#b48ae7':'#78a9d6';
function historyRecords(all){const groups=new Map(),out=[];for(const w of all){const t=dashType(w.type).id;if(!groups.has(t))groups.set(t,[]);groups.get(t).push(w);}for(const [t,rows] of groups){let seen5=false,seen4=false,n5=0,n4=0,ordinal=0;for(const w of rows.slice().reverse()){ordinal++;n5++;n4++;const rank=Number(w.rank),series=seen5?n5:null;let p=null;if(rank===5){p=seen5?n5:null;seen5=true;n5=0;}else if(rank===4){p=seen4?n4:null;seen4=true;n4=0;}out.push({w,t,rank,p,series,ordinal});}}return out.sort((a,b)=>sortWishes(a.w,b.w));}
function makeHistoryRow(r){const w=r.w,v=lookupWish(w),row=dashNode('div','wish-history-row');row.dataset.rank=String(r.rank);const body=dashNode('div','wish-row-body'),info=dashNode('div','wish-row-text');if(r.rank>=4)body.append(iconFor(v,r.rank));info.append(dashNode('strong','wish-row-name',cleanGameName(v?.n||w.name)),dashNode('small','wish-row-detail',dashDate(w.time)+' · '+'★'.repeat(r.rank)+(v?.k==='characters'?' · персонаж':v?.k==='weapons'?' · оружие':'')));body.append(info);const count=r.rank===3?(r.series===null?'—':fmt(r.series)+' / 5★'):r.p===null?'?':fmt(r.p)+' крут.';row.append(dashNode('span','wish-ordinal','№'+fmt(r.ordinal)),body,dashNode('span','wish-row-count',count));return row;}
function historyJump(type){const el=document.getElementById('history-block-'+type);if(el?.scrollIntoView)el.scrollIntoView({behavior:'smooth',block:'start'});}
function openHistory(type){historyRank='all';$('#historySearch').value='';navigate('wishes');if(type)historyJump(type);}
function renderHistory(force=false){const q=normalize($('#historySearch').value),key=[historyRevision,historyRank,q].join('|');if(!force&&key===historyKey)return;historyKey=key;const all=historyRecords(wishesFor('all')),wrap=$('#historyBlocks'),quick=$('#historyQuick');wrap.replaceChildren();quick.replaceChildren();let shown=0;for(const d of DASH_TYPES){const source=all.filter(r=>r.t===d.id);if(d.id==='other'&&!source.length)continue;const list=source.filter(r=>(historyRank==='all'||String(r.rank)===historyRank)&&(!q||[r.w.name,lookupWish(r.w)?.n,lookupWish(r.w)?.en,r.w.item].some(n=>normalize(n).includes(q))));shown+=list.length;const jump=dashNode('button','history-jump',d.symbol+' '+d.short+' · '+fmt(source.length));jump.style.setProperty('--group-color',d.color);jump.onclick=()=>historyJump(d.id);quick.append(jump);const card=dashNode('article','panel wish-history-block');card.id='history-block-'+d.id;card.style.setProperty('--group-color',d.color);const title=dashNode('div','wish-block-title');title.append(dashNode('span','wish-block-symbol',d.symbol),dashNode('h3','',d.label));card.append(title,dashNode('div','wish-block-total',fmt(source.length)+' молитв'));const stats=dashNode('div','wish-block-summary');for(const [label,value] of [['5★',source.filter(r=>r.rank===5).length],['4★',source.filter(r=>r.rank===4).length],['3★',source.filter(r=>r.rank===3).length],...(d.cap?[['pity / '+d.cap,source.length?(source.some(r=>r.rank===5)?'':'≥')+pity(d.id):'—']]:[])]){const m=dashNode('div');m.append(dashNode('strong','',value),dashNode('small','',label));stats.append(m);}card.append(stats);const header=dashNode('div','wish-list-head');header.append(dashNode('span','','№'),dashNode('span','','Предмет / дата'),dashNode('span','','Счётчик'));card.append(header);const rows=dashNode('div','wish-block-rows');rows.tabIndex=0;rows.setAttribute('aria-label','Все молитвы: '+d.label);if(!list.length)rows.append(dashNode('p','hint history-empty',source.length?'Нет совпадений.':'Нет импортированных молитв.'));else for(let i=0;i<list.length;i+=80){const chunk=dashNode('div','wish-row-chunk');for(const r of list.slice(i,i+80))chunk.append(makeHistoryRow(r));rows.append(chunk);}card.append(rows,dashNode('p','wish-block-footer',fmt(list.length)+' из '+fmt(source.length)+' записей · прокручивай список'));wrap.append(card);}write('#historyCount',fmt(all.length)+' молитв в истории · отображено '+fmt(shown));for(const b of document.querySelectorAll('[data-history-rank]')){const yes=b.dataset.historyRank===historyRank;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));}}
