let profileSelection=null,profileLimit=24;

function weaponItem(c){const v=lookupItem(c.itemId)||lookupItem(c.name);return v?.k==='weapons'?v:null;}
function collectionKey(v){return v.k+':'+v.id;}
function unhideCollection(v){state.collectionHidden=state.collectionHidden.filter(k=>k!==collectionKey(v));}
function syncCollection(){let changed=false,added=0;const counts=new Map(),seen=new Set();for(const w of state.wishes){const v=lookupWish(w);if(!v||!['characters','weapons'].includes(v.k))continue;const key=typeOf(w.type)+':'+w.id;if(w.id!=null&&seen.has(key))continue;if(w.id!=null)seen.add(key);const k=collectionKey(v);const old=counts.get(k);counts.set(k,{v,n:(old?.n||0)+1});}
for(const [kind,list,resolve] of [['characters',state.characters,profileItem],['weapons',state.weapons,weaponItem]]){for(const row of list){const v=resolve(row);if(!v)continue;const n=counts.get(collectionKey(v))?.n||0;if(row.historyCopies!==n){row.historyCopies=n;changed=true;}if(kind==='characters'){if(row.constellationMode==null){row.constellationMode=row.constellation==null?'auto':'manual';changed=true;}if(row.constellationMode==='auto'){const next=n?Math.min(6,n-1):null;if(row.constellation!==next){row.constellation=next;changed=true;}}}}}
for(const [key,{v,n}] of counts){if(state.collectionHidden.includes(key))continue;const list=v.k==='characters'?state.characters:state.weapons,resolve=v.k==='characters'?profileItem:weaponItem;if(list.some(c=>resolve(c)?.id===v.id))continue;const base={itemId:v.id,name:v.n,level:null,historyCopies:n};list.push(v.k==='characters'?{...base,constellation:Math.min(6,n-1),constellationMode:'auto'}:{...base,ownedCopies:null,refinement:null});changed=true;added++;}
if(changed)save();return added;}
function collectionCountLabel(c){return 'Из молитв: '+fmt(c.historyCopies||0)+' коп.';}
function profileAutoButton(c){const b=dashNode('button','ghost collection-auto','↻ По истории');b.type='button';b.title='Сбросить ручное созвездие и считать по известным молитвам';b.onclick=()=>{c.constellationMode='auto';c.constellation=c.historyCopies?Math.min(6,c.historyCopies-1):null;save();renderProfile();if(profileSelection?.id===profileItem(c)?.id)chooseProfile(profileSelection);};return b;}
function hideCollection(c,v,kind){const list=state[kind],i=list.indexOf(c);if(i>=0)list.splice(i,1);if(v&&!state.collectionHidden.includes(collectionKey(v)))state.collectionHidden.push(collectionKey(v));save();renderProfile();}
let arsenalSelection=null,arsenalLimit=18;
function renderArsenalPicker(){const q=normalize($('#arsenalPickSearch').value),rows=CATALOG.filter(v=>v.k==='weapons'&&(!q||[v.n,v.en,v.id].some(t=>normalize(t).includes(q)))).sort((a,b)=>b.r-a.r||a.n.localeCompare(b.n,'ru'));const root=$('#arsenalPickMatches');root.replaceChildren();for(const v of rows.slice(0,arsenalLimit)){const btn=dashNode('button','profile-choice'+(arsenalSelection?.id===v.id?' selected':''));btn.type='button';btn.dataset.rank=String(v.r);btn.append(iconFor(v,v.r),dashNode('strong','',v.n),dashNode('small','profile-choice-stars','★'.repeat(v.r)));btn.onclick=()=>{arsenalSelection=v;$('#arsenalPickSelected').replaceChildren(itemLabel(v,v.n,'★'.repeat(v.r),v.r));$('#arsenalAdd').disabled=false;renderArsenalPicker();};root.append(btn);}if(!rows.length)root.append(dashNode('p','hint','Ничего не найдено.'));$('#arsenalPickMore').hidden=rows.length<=arsenalLimit;}
function arsenalCard(c){const v=weaponItem(c),card=dashNode('article','profile-card arsenal-card');card.dataset.rank=String(v?.r||0);const art=dashNode('div','profile-card-art');art.append(iconFor(v,v?.r),dashNode('span','profile-const-badge',c.refinement==null?'R?':'R'+c.refinement));const info=dashNode('div','profile-card-info');info.append(dashNode('h4','',v?.n||c.name),dashNode('span','profile-choice-stars','★'.repeat(v?.r||0)),dashNode('small','collection-source',collectionCountLabel(c)));const controls=dashNode('div','profile-card-controls');for(const [key,label,min,max] of [['ownedCopies','Есть копий',0,99999],['level','Уровень',1,90],['refinement','Пробуждение',1,5]]){const lab=dashNode('label','',label),input=document.createElement('input');input.type='number';input.min=String(min);input.max=String(max);input.placeholder='?';input.value=c[key]==null?'':String(c[key]);input.onchange=()=>{c[key]=input.value===''?null:Math.max(min,Math.min(max,num(input.value)));save();renderProfile();};lab.append(input);controls.append(lab);}info.append(controls);const actions=dashNode('div','profile-card-actions'),up=dashNode('button','ghost','Прокачка →'),del=dashNode('button','ghost profile-delete','Скрыть');up.disabled=!v||!UP.upgrades.weapons[v.id];up.onclick=()=>{navigate('upgrade');changeUpgradeKind('weapons',v.id);$('#upFrom').value=String(c.level??1);$('#upFromAsc').checked=false;calcUpgrade();};del.onclick=()=>hideCollection(c,v,'weapons');actions.append(up,del);info.append(actions);card.append(art,info);return card;}
function renderArsenal(){const q=normalize($('#arsenalSearch').value),r=$('#arsenalRarity').value,root=$('#arsenalList');root.replaceChildren();const rows=state.weapons.filter(c=>{const v=weaponItem(c);return (r==='all'||String(v?.r)===r)&&(!q||[c.name,v?.n,v?.en].some(t=>normalize(t).includes(q)));}).sort((a,b)=>(weaponItem(b)?.r||0)-(weaponItem(a)?.r||0)||String(a.name).localeCompare(String(b.name),'ru'));for(const c of rows)root.append(arsenalCard(c));if(!rows.length)root.append(dashNode('p','hint','Нет оружия по выбранным условиям.'));}
function initArsenal(){$('#arsenalSearch').oninput=$('#arsenalRarity').onchange=renderArsenal;$('#arsenalPickSearch').oninput=()=>{arsenalLimit=18;renderArsenalPicker();};$('#arsenalPickMore').onclick=()=>{arsenalLimit+=24;renderArsenalPicker();};$('#arsenalAdd').onclick=()=>{const v=arsenalSelection;if(!v)return;unhideCollection(v);if(!state.weapons.some(c=>weaponItem(c)?.id===v.id))state.weapons.push({itemId:v.id,name:v.n,historyCopies:0,ownedCopies:1,level:null,refinement:null});syncCollection();save();renderProfile();notice('Оружие добавлено в коллекцию.');};renderArsenalPicker();}

function profileItem(c){const v=lookupItem(c.itemId)||lookupItem(c.name);return v?.k==='characters'?v:null;}
function profileDetail(v){const m=PROFILE_META[v?.id]||{};return [ELEMENTS[m.el],WEAPON_TYPES[m.wp]].filter(Boolean).join(' · ');}
function profileExisting(v){return state.characters.find(c=>profileItem(c)?.id===v.id);}
function chooseProfile(v){profileSelection=v;const existing=profileExisting(v),root=$('#profileSelected');root.replaceChildren(itemLabel(v,v.n,profileDetail(v)||'★'.repeat(v.r),v.r));$('#characterLevel').value=String(existing?.level??1);$('#characterConst').value=String(existing?.constellation??0);$('#addCharacter').disabled=false;$('#addCharacter').textContent=existing?'✦ Сохранить параметры':'✦ Добавить в коллекцию';renderProfilePicker();}
function renderProfilePicker(){const q=normalize($('#profileSearch').value),rarity=$('#profileRarity').value,element=$('#profileElement').value;const rows=CATALOG.filter(v=>v.k==='characters'&&(rarity==='all'||String(v.r)===rarity)&&(element==='all'||PROFILE_META[v.id]?.el===element)&&(!q||[v.n,v.en,v.id].some(n=>normalize(n).includes(q)))).sort((a,b)=>b.r-a.r||a.n.localeCompare(b.n,'ru'));const root=$('#profileMatches');root.replaceChildren();for(const v of rows.slice(0,profileLimit)){const btn=dashNode('button','profile-choice'+(profileSelection?.id===v.id?' selected':''));btn.type='button';btn.dataset.rank=String(v.r);btn.setAttribute('aria-pressed',String(profileSelection?.id===v.id));btn.append(iconFor(v,v.r),dashNode('strong','',v.n),dashNode('small','profile-choice-stars','★'.repeat(v.r)),dashNode('small','',ELEMENTS[PROFILE_META[v.id]?.el]||''));if(profileExisting(v))btn.append(dashNode('span','profile-owned','✓'));btn.onclick=()=>chooseProfile(v);root.append(btn);}if(!rows.length)root.append(dashNode('p','hint','Ничего не найдено.'));write('#profileMatchesCount','Найдено: '+fmt(rows.length));$('#profileMore').hidden=rows.length<=profileLimit;}
function profileHeader(){const uid=String(state.uid||'').trim();$('#enkaLink').href=/^\d{9,10}$/.test(uid)?'https://enka.network/u/'+uid+'/':'https://enka.network/';write('#profileDisplayName',state.nickname||'Путешественник');write('#profileDisplayUid','UID '+(uid||'не указан')+' · '+({eu:'Европа',os:'Азия',usa:'Америка',cn:'Китай'}[state.server]||'Сервер не указан'));const root=$('#profileStats');root.replaceChildren();const five=state.characters.filter(c=>profileItem(c)?.r===5).length,four=state.characters.filter(c=>profileItem(c)?.r===4).length;dashMetric(root,'В коллекции',fmt(state.characters.length),'персонажей');dashMetric(root,'Легендарные',fmt(five),'5★');dashMetric(root,'Эпические',fmt(four),'4★');dashMetric(root,'Оружие',fmt(state.weapons.length),'видов');}
function profileCard(c){const v=profileItem(c),card=dashNode('article','profile-card');card.dataset.rank=String(v?.r||0);const art=dashNode('div','profile-card-art');art.append(iconFor(v,v?.r),dashNode('span','profile-const-badge',c.constellation==null?'C?':(c.constellationMode==='auto'?'≥ ':'')+'C'+c.constellation));card.append(art);const info=dashNode('div','profile-card-info');info.append(dashNode('h4','',v?.n||c.name),dashNode('span','profile-choice-stars','★'.repeat(v?.r||0)),dashNode('small','',profileDetail(v)||'Данные стихии не указаны'),dashNode('small','collection-source',collectionCountLabel(c)+' · '+(c.constellationMode==='manual'?'вручную':'оценка C')));const controls=dashNode('div','profile-card-controls');for(const [key,label,max] of [['level','Уровень',90],['constellation','Созвездие',6]]){const lab=dashNode('label','',label),sel=document.createElement('select');const blank=document.createElement('option');blank.value='';blank.textContent='?';sel.append(blank);for(let i=key==='level'?1:0;i<=max;i++){const o=document.createElement('option');o.value=String(i);o.textContent=key==='level'?String(i):'C'+i;sel.append(o);}sel.value=c[key]==null?'':String(c[key]);sel.onchange=()=>{c[key]=sel.value===''?null:Number(sel.value);if(key==='constellation')c.constellationMode='manual';save();renderProfile();};lab.append(sel);controls.append(lab);}info.append(controls);const acts=dashNode('div','profile-card-actions');const up=dashNode('button','ghost','Прокачка →');up.type='button';up.disabled=!v||!UP.upgrades.characters[v.id];up.onclick=()=>{navigate('upgrade');changeUpgradeKind('characters',v.id);$('#upFrom').value=String(c.level??1);$('#upFromAsc').checked=false;calcUpgrade();};const del=dashNode('button','ghost profile-delete','Удалить');del.type='button';del.onclick=()=>{hideCollection(c,v,'characters');if(profileSelection?.id===v?.id)chooseProfile(profileSelection);};acts.append(up,del);info.append(acts);if(c.constellationMode==='manual'&&c.historyCopies)info.append(profileAutoButton(c));card.append(info);return card;}
function renderProfile(){profileHeader();const q=normalize($('#collectionSearch').value),sort=$('#collectionSort').value;const rows=state.characters.filter(c=>!q||[c.name,profileItem(c)?.n,profileItem(c)?.en].some(n=>normalize(n).includes(q)));rows.sort((a,b)=>(sort==='level'?num(b.level)-num(a.level):sort==='rarity'?(profileItem(b)?.r||0)-(profileItem(a)?.r||0):0)||String(profileItem(a)?.n||a.name).localeCompare(String(profileItem(b)?.n||b.name),'ru'));const root=$('#characterList');root.replaceChildren();for(const c of rows)root.append(profileCard(c));if(!rows.length)root.append(dashNode('p','hint',state.characters.length?'Поиск ничего не нашёл.':'Коллекция пока пуста. Выбери героя слева или пополни её из истории молитв.'));renderProfilePicker();renderArsenal();write('#collectionSyncNote','Автоматическая синхронизация включена · скрыто записей: '+fmt(state.collectionHidden.length));}
function addProfileCharacter(){const v=profileSelection;if(!v)return notice('Выбери персонажа из базы.');const level=Math.max(1,Math.min(90,num($('#characterLevel').value))),constellation=Math.max(0,Math.min(6,num($('#characterConst').value)));const existing=profileExisting(v);unhideCollection(v);if(existing)Object.assign(existing,{itemId:v.id,name:v.n,level,constellation,constellationMode:'manual'});else state.characters.push({itemId:v.id,name:v.n,level,constellation,constellationMode:'manual'});syncCollection();save();renderProfile();chooseProfile(v);notice(existing?'Параметры персонажа обновлены.':'Персонаж добавлен в коллекцию.');}
function populateProfileFromWishes(){const added=syncCollection();renderProfile();if(profileSelection)chooseProfile(profileSelection);notice('Коллекция сверена. Новых записей: '+fmt(added)+'. Ручные параметры сохранены.');return added;}
function initProfile(){for(const id of ['profileSearch','profileRarity','profileElement'])document.getElementById(id).addEventListener(id==='profileSearch'?'input':'change',()=>{profileLimit=24;renderProfilePicker();});$('#profileMore').onclick=()=>{profileLimit+=24;renderProfilePicker();};$('#collectionSearch').oninput=$('#collectionSort').onchange=renderProfile;$('#addCharacter').onclick=addProfileCharacter;$('#profileFromHistory').onclick=populateProfileFromWishes;initArsenal();}

const goalPickers={};
function goalPicker(id,kind,key){const p={id,kind,key,limit:12,open:false};goalPickers[id]=p;const node=s=>document.getElementById(id+s);p.render=()=>{const q=normalize(node('Search').value),v=lookupItem(state[key]),list=CATALOG.filter(x=>x.k===kind&&x.r===5&&(!q||[x.n,x.en,x.id].some(n=>normalize(n).includes(q)))).sort((a,b)=>a.n.localeCompare(b.n,'ru'));const root=node('Matches');root.replaceChildren();for(const x of list.slice(0,p.limit)){const btn=dashNode('button','goal-choice'+(v?.id===x.id?' selected':''));btn.type='button';btn.setAttribute('aria-pressed',String(v?.id===x.id));btn.append(iconFor(x,5),dashNode('span','',x.n));btn.onclick=()=>{setSavedField(key,x.n);if(kind==='weapons'){setSavedField('goalIncludeWeapon',true);if(v?.id!==x.id)setSavedField('weaponPoint',false);}p.toggle(false);syncVisualTargets();renderCalc();};root.append(btn);}if(!list.length)root.append(dashNode('p','hint','Ничего не найдено.'));node('More').hidden=list.length<=p.limit;};
p.toggle=show=>{p.open=show;node('Panel').hidden=!show;node('Toggle').setAttribute('aria-expanded',String(show));if(show){for(const other of Object.values(goalPickers))if(other!==p&&other.open)other.toggle(false);node('Search').value='';p.limit=12;p.render();node('Search').focus?.();}};
p.sync=()=>{const v=lookupItem(state[key]),valid=v&&v.k===kind&&v.r===5;const btn=node('Toggle');btn.replaceChildren(itemLabel(valid?v:null,valid?v.n:state[key]|| (kind==='characters'?'Выбрать персонажа':'Выбрать оружие'),valid?'★★★★★':'Поиск в архиве',valid?5:0),dashNode('span','goal-chevron',p.open?'⌃':'⌄'));node('Clear').hidden=!state[key];};
node('Toggle').onclick=()=>{p.toggle(!p.open);p.sync();};node('Search').oninput=()=>{p.limit=12;p.render();};node('More').onclick=()=>{p.limit+=24;p.render();};node('Clear').onclick=()=>{setSavedField(key,'');if(kind==='weapons'){setSavedField('goalIncludeWeapon',false);setSavedField('weaponPoint',false);}p.toggle(false);syncVisualTargets();renderCalc();};p.sync();return p;}
function initGoalPickers(){goalPicker('goalChar','characters','goalCharacter');goalPicker('goalWeapon','weapons','weaponWishName');}
function syncGoalPickers(){for(const p of Object.values(goalPickers))p.sync();const char=lookupItem(state.goalCharacter),sig=lookupItem(char?.sig),btn=$('#goalSignature');btn.hidden=!(sig&&sig.k==='weapons'&&sig.r===5);if(!btn.hidden){btn.textContent='⚔ Выбрать '+sig.n;btn.onclick=()=>{if(lookupItem(state.weaponWishName)?.id!==sig.id)setSavedField('weaponPoint',false);if(lookupItem(state.weaponWishName)?.id!==sig.id)setSavedField('weaponPoint',false);setSavedField('weaponWishName',sig.n);setSavedField('goalIncludeWeapon',true);syncVisualTargets();renderCalc();};}}

const visualState={};
function itemPicker(id,kind,onSelect,only5=false){const input=document.getElementById(id+'Search'),matches=document.getElementById(id+'Matches'),more=document.getElementById(id+'More'),selected=document.getElementById(id+'Selected');const p=visualState[id]={id,kind,only5,limit:12,value:null,onSelect};p.select=(v,notify=true)=>{p.value=v||null;selected.replaceChildren();if(v)selected.append(itemLabel(v,v.n,v.r?'★'.repeat(v.r):'Выбранный материал',v.r));else selected.textContent='Пока не выбрано';if(notify&&v)onSelect(v);};p.render=()=>{const q=normalize(input.value);let list=CATALOG.filter(v=>v.k===kind&&(!only5||v.r===5)&&(!q||[v.n,v.en,v.id].some(n=>normalize(n).includes(q))));if(kind==='items'&&!q){const priority=['mora','heros_wit','mystic_enhancement_ore','crown_of_insight','primogem','original_resin'];list.sort((a,b)=>{const f=v=>priority.includes(v.id)?priority.indexOf(v.id):100;return f(a)-f(b)||a.n.localeCompare(b.n,'ru');});}else list.sort((a,b)=>a.n.localeCompare(b.n,'ru'));matches.replaceChildren();for(const v of list.slice(0,p.limit)){const b=dashNode('button','visual-choice');b.type='button';b.append(iconFor(v,v.r),dashNode('span','',v.n));b.onclick=()=>{p.select(v);input.value=v.n;p.limit=12;p.render();};matches.append(b);}if(!list.length)matches.append(dashNode('p','hint','Ничего не найдено.'));more.hidden=list.length<=p.limit;};input.oninput=()=>{p.limit=12;p.render();};more.onclick=()=>{p.limit+=24;p.render();};p.select(null,false);p.render();return p;}
function setSavedField(key,value){state[key]=value;for(const el of document.querySelectorAll('[data-field]'))if(el.dataset.field===key){if(el.type==='checkbox')el.checked=!!value;else el.value=value;}save();}
function syncVisualTargets(){syncGoalPickers();for(const [id,key] of [['calcChar','goalCharacter'],['calcWeapon','weaponWishName']]){const p=visualState[id];if(p){const v=lookupItem(state[key]);if(v!==p.value)p.select(v&&v.k===p.kind&&v.r===5?v:null,false);}}const ch=lookupItem(state.goalCharacter),sig=lookupItem(ch?.sig),btn=$('#calcSignature');btn.hidden=!(sig&&sig.k==='weapons'&&sig.r===5);if(!btn.hidden){btn.textContent='⚔ Сигнатура: '+sig.n;btn.onclick=()=>{setSavedField('weaponWishName',sig.n);setSavedField('goalIncludeWeapon',true);syncVisualTargets();renderCalc();};}}
function selectResource(v){$('#resourceName').value=v.n;visualState.resourcePick?.select(v,false);}
function renderResourceSummary(){const done=state.resources.filter(r=>num(r.have)>=num(r.need)).length;const root=$('#resourceSummary');root.replaceChildren();dashMetric(root,'Целей',fmt(state.resources.length),'видов ресурсов');dashMetric(root,'Собрано',fmt(done),'полностью');dashMetric(root,'Осталось',fmt(state.resources.length-done),'видов ресурсов');}
function updateResourceCard(card,r){const remaining=Math.max(0,num(r.need)-num(r.have));card.querySelector('.resource-left').textContent=remaining?'Осталось '+fmt(remaining):'Собрано ✓';card.querySelector('.resource-progress i').style.width=Math.min(100,num(r.have)/Math.max(1,num(r.need))*100)+'%';card.classList.toggle('complete',remaining===0);}
function renderResources(){const list=$('#resourceList');list.replaceChildren();renderResourceSummary();if(!state.resources.length)list.append(dashNode('p','hint','Пока нет целей. Добавь материал из базы или расчёта прокачки.'));for(const [i,r] of state.resources.entries()){const v=lookupItem(r.itemId)||lookupItem(r.name),card=dashNode('article','resource-goal');const head=dashNode('div','resource-goal-head');head.append(itemLabel(v,r.name,'',v?.r));const del=dashNode('button','ghost resource-delete','×');del.type='button';del.setAttribute('aria-label','Удалить '+r.name);del.onclick=()=>{state.resources.splice(i,1);save();renderResources();renderMapFarm();};head.append(del);card.append(head);const fields=dashNode('div','resource-edit');for(const [key,title,min] of [['have','Есть',0],['need','Нужно',1]]){const label=dashNode('label','',title),input=document.createElement('input');input.type='number';input.min=String(min);input.value=String(num(r[key]));input.oninput=()=>{r[key]=Math.max(min,num(input.value));save();updateResourceCard(card,r);renderResourceSummary();renderMapFarm();};input.onchange=()=>{input.value=String(r[key]);};label.append(input);fields.append(label);}card.append(fields);const progress=dashNode('div','progress resource-progress');progress.append(dashNode('i'));card.append(progress,dashNode('span','resource-left'));list.append(card);updateResourceCard(card,r);}renderResin();}
function renderResin(){const cost=num($('#resinRuns').value)*num($('#resinCost').value),have=num($('#resinHave').value)+60*num($('#resinFragile').value),missing=Math.max(0,cost-have),minutes=missing*8;write('#resinResult',fmt(cost));write('#resinMissing',fmt(missing));write('#resinTime',Math.floor(minutes/60)+' ч '+minutes%60+' мин');}
function renderMapFarm(){const wrap=$('#mapFarmList');wrap.replaceChildren();const pending=state.resources.filter(r=>num(r.need)>num(r.have));if(!pending.length){wrap.append(dashNode('p','hint','Нет незакрытых целей. Добавь материалы в планировщик.'));return;}for(const r of pending.slice(0,12)){const v=lookupItem(r.itemId)||lookupItem(r.name);wrap.append(itemLabel(v,r.name,'Осталось: '+fmt(num(r.need)-num(r.have)),v?.r));}if(pending.length>12)wrap.append(dashNode('p','hint','Ещё '+(pending.length-12)+' в плане фарма.'));}
function initNewPages(){initProfile();initGoalPickers();itemPicker('calcChar','characters',v=>{setSavedField('goalCharacter',v.n);syncVisualTargets();renderCalc();},true);itemPicker('calcWeapon','weapons',v=>{if(lookupItem(state.weaponWishName)?.id!==v.id)setSavedField('weaponPoint',false);setSavedField('weaponWishName',v.n);setSavedField('goalIncludeWeapon',true);syncVisualTargets();renderCalc();},true);itemPicker('resourcePick','items',selectResource);syncVisualTargets();for(const [id,item] of [['walletGemIcon','primogem'],['walletFateIcon','intertwined_fate'],['resinIcon','original_resin']])document.getElementById(id).append(iconFor(lookupItem(item)));for(const b of document.querySelectorAll('[data-daily-preset]'))b.onclick=()=>{setSavedField('daily',num(b.dataset.dailyPreset));renderCalc();};for(const b of document.querySelectorAll('[data-resin]'))b.onclick=()=>{$('#resinCost').value=b.dataset.resin;renderResin();};for(const id of ['resinRuns','resinCost','resinHave','resinFragile'])document.getElementById(id).oninput=renderResin;renderMapFarm();}

function render(){syncCollection();renderWishes();renderCalc();renderProfile();renderResources();}
const titles={overview:'Обзор аккаунта',wishes:'История молитв',calculator:'Калькулятор круток',profile:'Профиль путешественника',resources:'Планировщик ресурсов',upgrade:'Мастерская возвышения',map:'Карта Тейвата',catalog:'Архив Тейвата',settings:'Настройки и данные'};
function navigate(tab){notice('');$$('.page').forEach(e=>e.classList.toggle('active',e.id===tab));$$('[data-tab]').forEach(e=>e.classList.toggle('active',e.dataset.tab===tab));write('#pageTitle',titles[tab]||titles.overview);if(tab==='catalog')renderCatalog();if(tab==='wishes')renderHistory();if(tab==='map')renderMapFarm();if(tab==='resources')renderResources();if(tab==='calculator')syncVisualTargets();if(tab==='profile')renderProfile();window.scrollTo({top:0,behavior:'instant'});}
$$('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='wishes')openHistory();else navigate(b.dataset.tab);});$$('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='wishes')openHistory();else navigate(b.dataset.go);});
$$('[data-field]').forEach(el=>{const k=el.dataset.field;el.type==='checkbox'?el.checked=Boolean(state[k]):el.value=state[k]??'';el.addEventListener('input',()=>{state[k]=el.type==='checkbox'?el.checked:el.type==='number'?num(el.value):el.value;save();renderCalc();if(k==='uid'||k==='nickname'||k==='server')profileHeader();if(k==='nickname')renderDashboard();if(k==='server')renderDashCurrent();for(const other of document.querySelectorAll('[data-field]'))if(other!==el&&other.dataset.field===k){if(other.type==='checkbox')other.checked=!!state[k];else other.value=state[k];}if(k==='weaponWishName'||k==='goalCharacter')syncVisualTargets();});});

$('#wishFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>40*1024*1024)throw Error('Файл больше 40 МБ.');let incoming=extract(JSON.parse((await f.text()).replace(/^\uFEFF/,'')));if(!incoming.length)throw Error('Не найдены записи молитв. Проверь формат JSON.');const ids=[...new Set(incoming.map(w=>w.uid).filter(Boolean))];if(ids.length){let selected=String(state.uid||'').trim();if(selected&&!ids.includes(selected))throw Error('UID файла отличается от UID профиля.');if(!selected&&ids.length>1){selected=String(prompt('В файле несколько аккаунтов. Введи нужный UID: '+ids.join(', '),'')||'').trim();if(!ids.includes(selected))throw Error('Аккаунт не выбран.');}if(!selected)selected=ids[0];incoming=incoming.filter(w=>!w.uid||w.uid===selected);if(!state.uid){state.uid=selected;$('[data-field="uid"]').value=state.uid;}}const map=new Map(state.wishes.map(w=>[typeOf(w.type)+':'+w.id,w]));const before=map.size;incoming.forEach(w=>map.set(w.type+':'+w.id,w));state.wishes=[...map.values()].sort(sortWishes);save();render();notice('Импортировано '+incoming.length+' записей, новых: '+(map.size-before)+'.');}catch(err){notice('Ошибка импорта: '+err.message);}finally{e.target.value='';}};
$('#addResource').onclick=()=>{const v=visualState.resourcePick?.value;if(!v)return notice('Выбери материал из базы.');const need=Math.max(1,num($('#resourceNeed').value)),have=num($('#resourceHave').value),old=state.resources.find(r=>r.itemId===v.id||normalize(r.name)===normalize(v.n));if(old){old.need=num(old.need)+need;old.have=Math.max(num(old.have),have);}else state.resources.push({name:v.n,itemId:v.id,need,have});save();renderResources();renderMapFarm();notice('Материал добавлен в план.');};

$('#enkaBtn').onclick=async()=>{const uid=String(state.uid||'').trim();if(!/^\d{9,10}$/.test(uid))return notice('Введи корректный UID (9–10 цифр).');const out=$('#enkaOutput');out.textContent='Пробуем получить публичную витрину…';const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);try{const r=await fetch('https://enka.network/api/uid/'+uid+'/',{signal:ctrl.signal});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json(),p=d.playerInfo||{};out.textContent='Имя: '+(p.nickname||'не указано')+' · Уровень приключений: '+(p.level??'—')+' · Персонажей в витрине: '+(d.avatarInfoList?.length??0)+'. Полный инвентарь по UID недоступен.';if(p.nickname&&!state.nickname){state.nickname=p.nickname;$('[data-field="nickname"]').value=p.nickname;save();profileHeader();renderDashboard();}}catch{out.textContent='Автоматическая загрузка недоступна (CORS, сеть или ограничения Enka). Открой профиль по ссылке и добавь персонажей вручную.';}finally{clearTimeout(timer);}};
function download(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('#backupBtn').onclick=()=>download({app:'noctis-genshin-planner',version:1,exportedAt:new Date().toISOString(),data:state},'noctis-backup.json');
$('#restoreFile').onchange=async e=>{try{const f=e.target.files?.[0];if(!f)return;const x=JSON.parse(await f.text());if(x.app!=='noctis-genshin-planner'||!x.data||!Array.isArray(x.data.wishes)||!Array.isArray(x.data.resources)||!Array.isArray(x.data.characters))throw Error('Неверный формат резервной копии.');if(!confirm('Заменить все текущие данные резервной копией?'))return;state={...defaults(),...x.data};save();location.reload();}catch(err){notice('Не удалось восстановить копию: '+err.message);}finally{e.target.value='';}};
$('#clearBtn').onclick=()=>{if(confirm('Точно удалить все локальные данные? Это действие нельзя отменить без резервной копии.')){localStorage.removeItem(KEY);location.reload();}};

const UP=window.NOCTIS_UPGRADES||{upgrades:{characters:{},weapons:{}},characterXP:[],weaponXP:[],talent:[]};
let calculatedMaterials={};

let upgradeLimit=30;
function upgradeEntries(){const kind=$('#upKind').value,q=normalize($('#upSearch').value),rarity=$('#upRarity').value,group=UP.upgrades[kind]||{};return Object.keys(group).map(id=>({id,v:CATALOG.find(x=>x.k===kind&&x.id===id)||lookupItem(id),entry:group[id]})).filter(x=>(rarity==='all'||String(x.entry.r)===rarity)&&(!q||[x.id,x.v?.n,x.v?.en,lookupItem(x.v?.sig)?.n].some(v=>normalize(v).includes(q)))).sort((a,b)=>b.entry.r-a.entry.r||(a.v?.n||a.id).localeCompare(b.v?.n||b.id,'ru'));}
function changeUpgradeKind(kind,preferred){$('#upKind').value=kind;$('#upSearch').value='';$('#upRarity').value='all';upgradeLimit=30;fillUpgrade(preferred);}
function fillUpgrade(preferred){const kind=$('#upKind').value,sel=$('#upItem'),group=UP.upgrades[kind]||{},prev=preferred||sel.value;sel.replaceChildren();for(const id of Object.keys(group)){const opt=document.createElement('option');opt.value=id;opt.textContent=lookupItem(id)?.n||id;sel.append(opt);}sel.value=Object.hasOwn(group,prev)?prev:'';$$('[data-up-kind]').forEach(b=>{const active=b.dataset.upKind===kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('#upTalent').hidden=kind!=='characters';renderUpgradeMatches();renderUpgradeSelected();calcUpgrade();}
function selectUpgrade(id){const sel=$('#upItem');if(!Object.hasOwn(UP.upgrades[$('#upKind').value]||{},id))return;sel.value=id;const e=UP.upgrades[$('#upKind').value][id];const max=e.stages.length<6?([20,40,50,60,70,80][e.stages.length]||90):90;for(const key of ['upFrom','upTo']){const el=$('#'+key);if(Number(el.value)>max)el.value=String(max);}renderUpgradeMatches();renderUpgradeSelected();calcUpgrade();}
function renderUpgradeMatches(){const list=$('#upMatches'),entries=upgradeEntries();list.replaceChildren();$('#upCount').textContent=fmt(entries.length)+' найдено';$('#upMore').hidden=entries.length<=upgradeLimit;if(!entries.length){const p=document.createElement('p');p.className='hint up-empty';p.textContent='Ничего не найдено. Попробуй другое имя или сними фильтр редкости.';list.append(p);return;}for(const x of entries.slice(0,upgradeLimit)){const b=document.createElement('button');b.type='button';b.className='up-choice'+(x.id===$('#upItem').value?' selected':'');b.setAttribute('aria-pressed',String(x.id===$('#upItem').value));const info=document.createElement('span'),n=document.createElement('strong'),stars=document.createElement('small');n.textContent=x.v?.n||x.id;stars.textContent='★'.repeat(x.entry.r);info.append(n,stars);b.append(iconFor(x.v,x.entry.r),info);b.onclick=()=>selectUpgrade(x.id);list.append(b);}}
function renderUpgradeSelected(){const el=$('#upSelected'),kind=$('#upKind').value,id=$('#upItem').value,entry=UP.upgrades[kind]?.[id];el.replaceChildren();if(!entry){el.textContent='Выбери персонажа или оружие слева.';return;}const v=CATALOG.find(x=>x.k===kind&&x.id===id)||lookupItem(id),info=document.createElement('div'),tag=document.createElement('div'),name=document.createElement('h4'),stars=document.createElement('div');tag.className='eyebrow';tag.textContent=kind==='characters'?'ПЕРСОНАЖ':'ОРУЖИЕ';name.textContent=v?.n||id;stars.className='gold';stars.textContent='★'.repeat(entry.r);info.append(tag,name,stars);if(v?.sig){const sig=lookupItem(v.sig);if(sig&&UP.upgrades.weapons[sig.id]){const b=document.createElement('button');b.className='ghost sig-link';b.type='button';b.textContent='⚔ '+sig.n+' →';b.onclick=()=>changeUpgradeKind('weapons',sig.id);info.append(b);}}el.append(iconFor(v,entry.r),info);}

function calcUpgrade(){const kind=$('#upKind').value,id=$('#upItem').value,entry=UP.upgrades[kind]?.[id],out=$('#upResults'),warning=$('#upWarning');out.replaceChildren();calculatedMaterials={};const from=num($('#upFrom').value),to=num($('#upTo').value);const caps=[20,40,50,60,70,80];const stage=(l,asc)=>caps.filter(x=>l>x||(asc&&l===x)).length;let messages=[];let invalid=false;const fail=m=>{warning.textContent=m;$('#upSummary').textContent='';$('#upAdd').disabled=true;$('#upCopy').disabled=true;};if(!entry)return fail('Выбери персонажа или оружие из базы.');const max=entry.stages.length<6?([20,40,50,60,70,80][entry.stages.length]||90):90;if(from<1||to<from||to>max)return fail('Уровни должны быть от 1 до '+max+', цель не ниже текущего.');const start=stage(from,$('#upFromAsc').checked),end=stage(to,$('#upToAsc').checked);if(start>end||end>entry.stages.length)return fail('Проверь отметки возвышения и предел уровня.');const add=(k,n)=>{if(k&&n>0)calculatedMaterials[k]=(calculatedMaterials[k]||0)+n;};for(const st of entry.stages.slice(start,end)){for(const [k,n] of st.items)add(k,n);add('mora',st.mora);}const xp=kind==='characters'?UP.characterXP:UP.weaponXP[entry.r-3];if(xp&&xp[to-1]!=null){const exp=xp[to-1]-xp[from-1];if(kind==='characters'){add('heros_wit',Math.ceil(exp/20000));add('mora',Math.ceil(exp/5));}else{add('mystic_enhancement_ore',Math.ceil(exp/10000));add('mora',Math.ceil(exp/10));}messages.push('Необходимо '+fmt(exp)+' опыта.');}else if(to>from)messages.push('Таблица опыта для этой редкости отсутствует; материалы возвышения рассчитаны отдельно.');
if(kind==='characters'){for(let i=0;i<3;i++){const f=num($('#talFrom'+i).value),t=num($('#talTo'+i).value);if(f<1||t<f||t>10)return fail('Уровни талантов должны быть от 1 до 10, цель не ниже текущего.');if(t>f&&(!entry.books||!entry.common||!entry.boss))return fail('Для этого персонажа в базе нет полной таблицы талантов. Установи одинаковые уровни талантов для расчёта только возвышения.');const required=[0,0,2,3,3,4,4,5,5,6,6][t];if(t>f&&required>end)return fail('Для таланта '+t+' требуется фаза возвышения '+required+'. Увеличь целевой уровень или отметь возвышение на пороге.');for(const [br,bn,cr,cn,boss,crown,mora] of UP.talent.slice(f-1,t-1)){add(entry.books[br-2],bn);add(entry.common[cr-1],cn);add(entry.boss,boss);add('crown_of_insight',crown);add('mora',mora);}}}
const pairs=Object.entries(calculatedMaterials).sort((a,b)=>a[0]==='mora'?-1:b[0]==='mora'?1:0);for(const [k,n] of pairs){const v=lookupItem(k),card=document.createElement('div');card.className='material-card';card.append(itemLabel(v,k,'',v?.r));const count=document.createElement('b');count.className='material-quantity';count.textContent=fmt(n);card.append(count);out.append(card);}if(!pairs.length)out.textContent='Для выбранной цели дополнительные материалы не нужны.';warning.textContent=messages.join(' ');$('#upSummary').textContent=pairs.length+' видов ресурсов';$('#upAdd').disabled=!pairs.length;$('#upCopy').disabled=!pairs.length;}
function initUpgrade(){$$('[data-up-kind]').forEach(b=>b.onclick=()=>changeUpgradeKind(b.dataset.upKind));$('#upSearch').addEventListener('input',()=>{upgradeLimit=30;renderUpgradeMatches();});$('#upRarity').addEventListener('change',()=>{upgradeLimit=30;renderUpgradeMatches();});$('#upMore').onclick=()=>{upgradeLimit+=30;renderUpgradeMatches();};$$('[data-step]').forEach(b=>b.onclick=()=>{const [id,delta]=b.dataset.step.split(':');const el=$('#'+id);el.value=String(Math.max(1,Math.min(90,num(el.value)+Number(delta))));calcUpgrade();});$$('[data-up-preset]').forEach(b=>b.onclick=()=>{const [f,t]=b.dataset.upPreset.split(':');$('#upFrom').value=f;$('#upTo').value=t;$('#upFromAsc').checked=false;$('#upToAsc').checked=false;calcUpgrade();});$$('[data-tal-preset]').forEach(b=>b.onclick=()=>{for(let n=0;n<3;n++){const f=num($('#talFrom'+n).value);$('#talTo'+n).value=String(b.dataset.talPreset==='same'?f:Math.max(f,Number(b.dataset.talPreset)));}calcUpgrade();});for(const id of ['upItem','upFrom','upTo','upFromAsc','upToAsc','talFrom0','talFrom1','talFrom2','talTo0','talTo1','talTo2'])$('#'+id).addEventListener('input',calcUpgrade);$('#upAdd').onclick=()=>{if(!Object.keys(calculatedMaterials).length)return;for(const [id,n] of Object.entries(calculatedMaterials)){const name=lookupItem(id)?.n||id;const existing=state.resources.find(r=>r.itemId===id||normalize(r.name)===normalize(name));if(existing)existing.need=num(existing.need)+n;else state.resources.push({name,itemId:id,need:n,have:0});}save();navigate('resources');notice('Материалы добавлены в общий план. Повторное добавление суммирует цели.');};$('#upCopy').onclick=async()=>{const str=Object.entries(calculatedMaterials).map(([id,n])=>(lookupItem(id)?.n||id)+': '+fmt(n)).join('\n');try{await navigator.clipboard.writeText(str);notice('Список скопирован.');}catch{notice('Не удалось скопировать список.');}};$('#mapEmbed').onclick=()=>{const wrap=$('#mapFrame');if(wrap.firstChild)return;const f=document.createElement('iframe');f.src='https://genshin-impact-map.appsample.com/ru/';f.title='Интерактивная карта Тейвата';f.referrerPolicy='no-referrer';f.loading='lazy';wrap.append(f);};fillUpgrade();}

let deferredPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').hidden=false;});$('#installBtn').onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installBtn').hidden=true;};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});migrateGameNames();initCatalog();initUpgrade();initDashboard();initHistory();initNewPages();render();
